#include <iostream>
#include <vector>
#include <utility>

int main() {
    int n = 0;
    std::cin >> n;
    std::vector<long long> v(n);
    for (int i = 0; i < n; ++i) {
        std::cin >> v[i];
    }
    for (std::size_t i = 0; i < v.size() / 2; ++i) {
        std::swap(v[i], v[v.size() - 1 - i]);
    }
    long long sum = 0;
    for (std::size_t i = 0; i < v.size(); ++i) {
        if (i > 0) std::cout << ' ';
        std::cout << v[i];
        sum += v[i];
    }
    std::cout << '\n' << sum << '\n';
    return 0;
}
